const fs = require('fs');

const input = fs.readFileSync(0, 'utf8');

let balance = 0;
let valid = true;

for (let i = 0; i < input.length; i++) {
  const c = input[i];
  if (c === '{') {
    balance++;
  } else if (c === '}') {
    balance--;
    if (balance < 0) {
      valid = false;
      break;
    }
  }
}

if (valid && balance === 0) {
  console.log('S');
} else {
  console.log('N');
}
